+	}
+	_, err = h.Q.UpdateSyncRunSuccess(ctx, database.UpdateSyncRunSuccessParams{
+		ID:        runID,
+		CommitSha: &commitPtr,
+	})
+	if err != nil {
+		return fmt.Errorf("update sync run success: %w", err)
+	}
+	return nil
+}
