329	+	if errors.As(syncErr, &sourceErr) {
330	+		code = string(sourceErr.Code)
331	+		message = sourceErr.Message
332	+	}
333	+	runID, err := h.ensureTaskSyncRun(ctx, payload, branch, false)
334	+	if err != nil {
335	+		log.Error().Err(err).Str("workspace_id", payload.WorkspaceID).Str("feature_id", payload.FeatureID).Str("task_id", payload.TaskID).AnErr("original_error", syncErr).Msg("ensure failed task sync run failed")
336	+		return
337	+	}
338	+	if _, err := h.Q.UpdateSyncRunFailed(ctx, database.UpdateSyncRunFailedParams{
339	+		ID:           runID,
340	+		ErrorCode:    &code,
341	+		ErrorMessage: &message,
342	+	}); err != nil {
343	+		log.Error().Err(err).Str("workspace_id", payload.WorkspaceID).Str("feature_id", payload.FeatureID).Str("task_id", payload.TaskID).AnErr("original_error", syncErr).Msg("update failed task sync run failed")
344	+	}
