347	+func (h *Handler) ensureTaskSyncRun(ctx context.Context, payload queue.TaskSyncPayload, branch string, requireRefs bool) (pgtype.UUID, error) {
348	+	uid, err := pgutil.PgUUID(payload.WorkspaceID)
349	+	if err != nil {
350	+		return pgtype.UUID{}, err
351	+	}
352	+	featureUUID, taskUUID, err := h.syncRunReferenceIDs(ctx, uid, payload.FeatureID, payload.TaskID)
353	+	if err != nil {
354	+		if requireRefs {
355	+			return pgtype.UUID{}, err
356	+		}
357	+		log.Warn().Err(err).Str("workspace_id", payload.WorkspaceID).Str("feature_id", payload.FeatureID).Str("task_id", payload.TaskID).Msg("could not resolve task sync run refs")
358	+		featureUUID = pgtype.UUID{}
359	+		taskUUID = pgtype.UUID{}
360	+	}
361	+	branchPtr := branch
362	+	row, err := h.Q.InsertSyncRun(ctx, database.InsertSyncRunParams{
363	+		WorkspaceID:  uid,
364	+		Trigger:      "webhook_task",
365	+		Branch:       &branchPtr,
366	+		FeatureID:    featureUUID,
367	+		TaskID:       taskUUID,
368	+		Mode:         "task",
369	+		Status:       "running",
370	+		ChangedPaths: []byte("[]"),
371	+	})
372	+	if err != nil {
373	+		return pgtype.UUID{}, fmt.Errorf("insert task sync run: %w", err)
374	+	}
375	+	return row.ID, nil
376	+}
