647	+// HandleWorkspaceSync processes workspace:sync jobs.
648	+func (h *Handler) HandleWorkspaceSync(ctx context.Context, t *asynq.Task) error {
649	+	var payload queue.WorkspaceSyncPayload
650	+	if err := json.Unmarshal(t.Payload(), &payload); err != nil {
651	+		return fmt.Errorf("unmarshal payload: %w", err)
652	+	}
653	+	if payload.RepoURL == "" {
654	+		return fmt.Errorf("repo_url is required: %w", asynq.SkipRetry)
655	+	}
656	+	if strings.TrimSpace(payload.WorkspaceID) == "" {
657	+		return fmt.Errorf("workspace_id is required for workspace sync: %w", asynq.SkipRetry)
658	+	}
659	+	if err := h.ensureWorkspaceExists(ctx, payload.WorkspaceID); err != nil {
660	+		return err
661	+	}
662	+	if payload.DefaultBranch == "" {
663	+		payload.DefaultBranch = "main"
664	+	}
665	+	ref := payload.Ref
666	+	if ref == "" {
667	+		ref = payload.DefaultBranch
668	+	}
669	+	trigger := payload.Trigger
670	+	if trigger == "" {
671	+		trigger = "redis_worker"
672	+	}
673	+	mode := payload.Mode
674	+	if mode == "" {
675	+		mode = "full"
676	+	}
677	+
678	+	// Targeted sync: fetch and upsert a single feature only.
679	+	if mode == "targeted" && payload.FeatureID != "" {
680	+		return h.handleTargetedSync(ctx, payload, trigger, ref)
681	+	}
682	+
683	+	// Full reconciliation: clear pending task-sync jobs first, then sync everything.
684	+	log.Info().Str("workspace_id", payload.WorkspaceID).Str("repo_url", payload.RepoURL).Str("ref", ref).Msg("sync started")
685	+
686	+	// Delete all pending task-sync jobs before full reconciliation starts.
687	+	// The full read supersedes all queued partial updates.
688	+	inspector := h.openPendingTaskInspector()
689	+	defer func() {
690	+		if err := inspector.Close(); err != nil {
691	+			log.Warn().Err(err).Msg("close asynq inspector")
692	+		}
693	+	}()
694	+	if _, err := clearPendingTaskSyncJobsForWorkspace(inspector, payload.WorkspaceID); err != nil {
695	+		err = fmt.Errorf("clear pending task-sync jobs for workspace %s: %w", payload.WorkspaceID, err)
696	+		h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
697	+		return err
698	+	}
699	+
700	+	snap, err := h.GitHub.ImportWorkspace(ctx, domain.ImportInput{
701	+		RepoURL:       payload.RepoURL,
702	+		DefaultBranch: ref,
703	+		Token:         h.Token,
704	+	})
705	+	if err != nil {
706	+		h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
707	+		return err
708	+	}
709	+	if err := firstSnapshotSourceError(snap); err != nil {
710	+		h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
711	+		return err
712	+	}
713	+	snap.WorkspaceID = payload.WorkspaceID
714	+	snap.RepoURL = payload.RepoURL
715	+	if strings.TrimSpace(payload.Name) != "" {
716	+		snap.Name = payload.Name
717	+		snap.Slug = urlutil.Slugify(payload.Name)
718	+	}
719	+
720	+	if err := h.DB.SaveSnapshot(ctx, payload.WorkspaceID, snap); err != nil {
721	+		h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
722	+		return err
723	+	}
724	+	if err := h.upsertGitHubSource(ctx, payload.WorkspaceID, payload.RepoURL, payload.DefaultBranch); err != nil {
725	+		h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
726	+		return err
727	+	}
728	+	if err := h.recordSuccessfulRun(ctx, payload, trigger, mode, ref, snap.CommitSHA); err != nil {
729	+		return err
730	+	}
731	+
732	+	log.Info().Str("workspace_id", payload.WorkspaceID).Str("commit_sha", snap.CommitSHA).Msg("sync finished")
733	+	return nil
734	+}
735	+
736	+func clearPendingTaskSyncJobsForWorkspace(inspector PendingTaskInspector, workspaceID string) (int, error) {
737	+	const pageSize = 100
738	+	deleted := 0
739	+	page := 1
740	+	for {
741	+		tasks, err := inspector.ListPendingTasks(queue.QueueTaskSync, asynq.Page(page), asynq.PageSize(pageSize))
742	+		if errors.Is(err, asynq.ErrQueueNotFound) {
743	+			return deleted, nil
744	+		}
745	+		if err != nil {
746	+			return deleted, fmt.Errorf("list pending task-sync jobs: %w", err)
747	+		}
748	+		if len(tasks) == 0 {
749	+			return deleted, nil
750	+		}
751	+
752	+		deletedFromPage := false
753	+		for _, info := range tasks {
754	+			if info.Type != queue.TypeTaskSync {
755	+				continue
756	+			}
757	+			var payload queue.TaskSyncPayload
758	+			if err := json.Unmarshal(info.Payload, &payload); err != nil {
759	+				continue
760	+			}
761	+			if payload.WorkspaceID != workspaceID {
762	+				continue
763	+			}
764	+			if err := inspector.DeleteTask(queue.QueueTaskSync, info.ID); err != nil {
765	+				return deleted, fmt.Errorf("delete pending task-sync job %s: %w", info.ID, err)
766	+			}
767	+			deleted++
768	+			deletedFromPage = true
769	+		}
770	+
771	+		if deletedFromPage {
772	+			page = 1
773	+			continue
774	+		}
775	+		if len(tasks) < pageSize {
776	+			return deleted, nil
777	+		}
778	+		page++
779	+	}
780	+}
781	+
782	+// handleTargetedSync fetches and upserts a single feature's artifacts.
783	+func (h *Handler) handleTargetedSync(ctx context.Context, payload queue.WorkspaceSyncPayload, trigger, ref string) error {
784	+	log.Info().Str("workspace_id", payload.WorkspaceID).Str("feature_id", payload.FeatureID).Str("ref", ref).Msg("targeted sync started")
785	+
786	+	snap, err := h.GitHub.FetchFeature(ctx, payload.RepoURL, ref, payload.FeatureID)
787	+	if err != nil {
788	+		h.recordFailedRun(ctx, payload, trigger, "targeted", ref, err)
789	+		return err
790	+	}
791	+
792	+	if err := h.DB.SaveFeatureSnapshot(ctx, payload.WorkspaceID, *snap); err != nil {
793	+		h.recordFailedRun(ctx, payload, trigger, "targeted", ref, err)
794	+		return err
795	+	}
796	+
797	+	runUID, err := h.ensureSyncRun(ctx, payload, trigger, "targeted", ref, nil, true)
798	+	if err != nil {
799	+		return err
800	+	}
801	+	_, err = h.Q.UpdateSyncRunSuccess(ctx, database.UpdateSyncRunSuccessParams{
802	+		ID: runUID,
803	+	})
804	+	if err != nil {
